python3 -c 'import sys,json,base64,zlib,time,os;i=sys.argv[1]if len(sys.argv)>1 else"all_repos_coordinate.json";o=sys.argv[2]if len(sys.argv)>2 else"afu_tiny.json";S=json.load(open(i,encoding="utf-8"))if os.path.exists(i)else{};G=int(S.get("G_all",0));R=S.get("rho_all","unbound");N=S.get("Manifest",{}).get("RepositoryCount",0);M={"P":"AFU-Tiny","A":"CL","r":R,"G":G,"n":N,"L":"now:H>0;dH<0;future:H=0","D":"as,ph,bio,cog,soc,tech,eco,tmp,cos,eth,ai,hum,pet,food","C":"nv,co,tr,ca,ju,st,ct,rv,gv","Hf":0,"Hb":1};b=json.dumps(M,sort_keys=True,separators=(",",":")).encode();z=zlib.compress(b,9);B=base64.b64encode(z).decode();g=(G+sum((i+1)*x for i,x in enumerate(z)))%1000000007;J={"Protocol":"CLZeroPack/AFU-Tiny/1.0","Payload":B,"G_future":g,"rho_future":"1/2+i*log(1+%d)"%g,"H_s":0 if zlib.decompress(base64.b64decode(B))==b else 1,"H_future":0,"H_current_boundary":1,"Manifest":M,"UTC":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())};open(o,"w",encoding="utf-8").write(json.dumps(J,separators=(",",":")));print(json.dumps({"o":o,"rho":J["rho_future"],"H_s":J["H_s"],"Hf":0,"Hb":1},separators=(",",":")))' "$@"
